const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults={theme:'base',mode:'system',color:'#48614c',layout:'search',width:'safe',font:'sans'};
const seed=[{id:'work',name:'工作空间',icon:'▣',scenes:[{id:'daily',name:'日常工作',description:'让常用工具各就其位，专注眼前的事情。',groups:[{id:'tools',name:'常用工具',items:[['Notion','https://www.notion.so','笔记、计划与想法的集合','N'],['飞书','https://www.feishu.cn','和团队一起，把事情做好','↗'],['Figma','https://www.figma.com','从一个想法，到一个好设计','F']]},{id:'inspiration',name:'灵感与参考',items:[['Are.na','https://www.are.na','为灵感留一块自由生长的地方','✳'],['Dribbble','https://dribbble.com','遇见世界各地的好设计','D'],['Pinterest','https://www.pinterest.com','收集那些让你停下来的画面','P']]}]},{id:'learn',name:'学习资料',description:'一点一点，拓宽自己的边界。',groups:[{id:'read',name:'值得读读',items:[['MDN','https://developer.mozilla.org','开放网络的学习手册','M'],['中国大学 MOOC','https://www.icourse163.org','把好奇心变成新的知识','学']]}]}]},{id:'life',name:'生活空间',icon:'⌂',scenes:[{id:'weekend',name:'慢慢生活',description:'工作之外，还有好多喜欢的事情。',groups:[{id:'leisure',name:'留给自己',items:[['豆瓣','https://www.douban.com','书、电影与生活的片刻','豆'],['哔哩哔哩','https://www.bilibili.com','今天也发现一些有趣的东西','b']]}]}]},{id:'create',name:'灵感空间',icon:'✳',scenes:[{id:'ai',name:'AI 探索',description:'为新想法，留一扇打开的窗。',groups:[{id:'assistants',name:'思考搭子',items:[['DeepSeek','https://chat.deepseek.com','换个角度，思考问题','D'],['Kimi','https://www.kimi.com','读资料，也聊新想法','K'],['千问','https://www.qianwen.com','让灵感更进一步','Q']]}]}]}];
let stored;try{stored=JSON.parse(localStorage.getItem('yiyu-prototype-v1')||'null')}catch{}let data=stored?.data||seed;let prefs={...defaults,...stored?.prefs},overrides=stored?.overrides||{},styles=stored?.styles||{},signed=stored?.signed||false;
let view='home',spaceId='work',sceneId='daily',scope='global',searchType='web',filter='',pending=null;
if(!data.some(s=>s.id===spaceId)){spaceId=data[0].id;sceneId=data[0].scenes[0].id}
if(!data.find(s=>s.id===spaceId).scenes.some(c=>c.id===sceneId))sceneId=data.find(s=>s.id===spaceId).scenes[0].id;
function persist(){try{localStorage.setItem('yiyu-prototype-v1',JSON.stringify({data,prefs,overrides,styles,signed}))}catch{toast('本机存储不可用，本次修改仅在当前页面保留')}}
const space=()=>data.find(s=>s.id===spaceId),scene=()=>space().scenes.find(s=>s.id===sceneId);let effective=()=>({...prefs});
function searchMarkup(){return `<div class="search-area"><div class="search-tabs"><button data-search="web" class="${searchType==='web'?'selected':''}">搜网页</button><button data-search="saved" class="${searchType==='saved'?'selected':''}">搜收藏</button></div><form class="search-box" id="search-form">${searchType==='web'?'<select id="engine" aria-label="搜索引擎"><option value="google">Google</option><option value="baidu">百度</option><option value="bing">必应</option></select>':'<span aria-hidden="true">⌕</span>'}<input id="search-input" aria-label="${searchType==='web'?'搜索网页':'搜索全部收藏'}" placeholder="${searchType==='web'?'从一个问题，开始探索':'寻找你收藏过的好东西'}" autocomplete="off"><span class="shortcut">/ 搜索</span><button class="submit" type="submit" aria-label="搜索">↗</button></form><div id="search-results"></div></div>`}
function allItems(){return data.flatMap(s=>s.scenes.flatMap(c=>c.groups.flatMap(g=>g.items.map(i=>({item:i,path:`${s.name} / ${c.name} / ${g.name}`})))))}
function savedSearch(){const q=$('#search-input').value.trim().toLowerCase();$('#search-results').innerHTML=q?`<div class="results">${allItems().filter(x=>x.item.join(' ').toLowerCase().includes(q)).map(x=>`<a class="result" href="${esc(x.item[1])}" target="_blank" rel="noopener noreferrer">${esc(x.item[0])}<small>${esc(x.path)}</small></a>`).join('')||'<div class="empty">还没有找到这个收藏，换个关键词试试。</div>'}</div>`:''}
function submitSearch(e){e.preventDefault();if(searchType==='saved'){savedSearch();return}const q=$('#search-input').value.trim();if(!q)return;const urls={google:'https://www.google.com/search?q=',baidu:'https://www.baidu.com/s?wd=',bing:'https://www.bing.com/search?q='};window.open(urls[$('#engine').value]+encodeURIComponent(q),'_blank','noopener,noreferrer')}
function workspace(){const s=space(),c=scene();$('#main').innerHTML=`<section class="workspace"><aside class="sidebar"><select class="space-select" id="space-select" aria-label="当前空间">${data.map(x=>`<option value="${x.id}" ${x.id===spaceId?'selected':''}>${x.icon} ${x.name}</option>`).join('')}</select><span class="eyebrow">MY SCENES</span>${s.scenes.map(x=>`<button class="scene-button ${x.id===sceneId?'active':''}" data-scene="${x.id}"><span>▤</span>${esc(x.name)}<small>${x.groups.reduce((n,g)=>n+g.items.length,0)}</small></button>`).join('')}<p class="sidebar-note">各有归处，自有秩序。<br>这里装着你的日常与灵感。</p></aside><div class="workspace-content"><div class="workspace-top"><div><span class="eyebrow">${esc(s.name)} / ${esc(c.name)}</span><h1>${esc(c.name)}</h1><p>${esc(c.description)}</p></div><button class="primary" data-action="add">＋ 收藏网址</button></div><div class="workspace-tools"><span>⌕</span><input id="filter" placeholder="在当前场景中查找…" aria-label="搜索当前场景" value="${esc(filter)}"><button data-action="scene-settings">◐ 场景外观</button></div><div id="groups"></div><p class="draft-label">${signed?'本机体验空间 · 非云端账号':'示例空间 · 收藏时登录，继续你的体验'}</p></div></section>`;renderGroups();$('#filter').oninput=e=>{filter=e.target.value;renderGroups()};$('#space-select').onchange=e=>goSpace(e.target.value)}
function renderGroups(){$('#groups').innerHTML=scene().groups.map(g=>{const items=g.items.map((item,index)=>({item,index})).filter(x=>x.item.join(' ').toLowerCase().includes(filter.toLowerCase()));return `<section class="group"><div class="group-heading"><h2>${esc(g.name)}</h2><span class="count">${items.length.toString().padStart(2,'0')}</span><div class="rule"></div><select data-group-style="${g.id}" aria-label="${esc(g.name)}展示样式"><option value="cards" ${styles[g.id]!=='list'?'selected':''}>卡片</option><option value="list" ${styles[g.id]==='list'?'selected':''}>列表</option></select></div><div class="cards ${styles[g.id]==='list'?'list':''}">${items.map(({item:i,index})=>`<article class="bookmark"><a href="${esc(i[1])}" target="_blank" rel="noopener noreferrer"><div class="bookmark-head"><span class="site-icon">${esc(i[3])}</span><strong>${esc(i[0])}</strong></div><p>${esc(i[2])}</p></a><button class="remove" aria-label="删除 ${esc(i[0])}" data-remove="${g.id}:${index}">×</button></article>`).join('')||'<div class="empty">这里还没有匹配的收藏</div>'}</div></section>`}).join('')}
function goSpace(id){spaceId=id;sceneId=space().scenes[0]?.id||null;view='space';filter='';render()}
function show(id){$(id).showModal()}function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800)}
function choices(key,options,p){return `<div class="segmented">${options.map(([v,t])=>`<button class="${p[key]===v?'selected':''}" data-pref="${key}" data-value="${v}">${t}</button>`).join('')}</div>`}
function inheritLabel(k){return scope==='scene'?`<small>${overrides[sceneId]?.[k]!==undefined?'已自定义':'跟随全局'}</small>`:''}
function add(){pending=null;$('#add-form').reset();$('#destination').innerHTML=data.flatMap(s=>s.scenes.flatMap(c=>c.groups.map(g=>`<option value="${s.id}:${c.id}:${g.id}" ${c.id===sceneId&&g.id===scene().groups[0].id?'selected':''}>${esc(s.name)} / ${esc(c.name)} / ${esc(g.name)}</option>`))).join('');show('#add')}
function savePending(){if(!pending)return;const[sid,cid,gid]=pending.destination.split(':'),g=data.find(s=>s.id===sid).scenes.find(c=>c.id===cid).groups.find(g=>g.id===gid);g.items.push([pending.title,pending.url,new URL(pending.url).hostname,pending.title.slice(0,1)]);pending=null;persist();spaceId=sid;sceneId=cid;view='space';filter='';render();toast('已收藏，保存在本机体验空间')}
$('#add-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);let url;try{url=new URL(f.get('url'));if(!['http:','https:'].includes(url.protocol))throw 0}catch{toast('请输入以 http 或 https 开头的网址');return}pending={url:url.href,title:f.get('title').trim(),destination:f.get('destination')};if(!pending.title){toast('请填写收藏名称');return}$('#add').close();if(!signed)show('#login');else savePending()};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const a=b.dataset.action;if(a==='home'){changeView('home')}if(a==='space'){view='space';render()}if(a==='settings'||a==='scene-settings'){scope=a==='scene-settings'?'scene':'global';renderSettings();show('#settings')}if(a==='close')b.closest('dialog').close();if(a==='dock'){const d=$('.dock');d.classList.toggle('open');b.setAttribute('aria-expanded',d.classList.contains('open'))}if(a==='login'){if(signed)toast('当前使用本机体验身份，尚未连接真实账号');else show('#login')}if(a==='demo-login'){signed=true;persist();$('#login').close();if(pending)savePending();else{render();toast('已进入本机体验空间')}}if(a==='add')add();if(a==='reset-scene'){delete overrides[sceneId];persist();render();renderSettings()}if(b.dataset.space)goSpace(b.dataset.space);if(b.dataset.scene){sceneId=b.dataset.scene;filter='';render()}if(b.dataset.search){searchType=b.dataset.search;if($('#quick-search')?.open){quickSearch()}else{home();$('#search-input').focus()}}if(b.dataset.scope){scope=b.dataset.scope;renderSettings()}if(b.dataset.pref){if(scope==='scene'){overrides[sceneId]??={};overrides[sceneId][b.dataset.pref]=b.dataset.value}else prefs[b.dataset.pref]=b.dataset.value;persist();render();renderSettings()}if(b.dataset.remove){if(!signed){show('#login');return}const[gid,index]=b.dataset.remove.split(':'),g=scene().groups.find(g=>g.id===gid);if(confirm(`从体验空间删除「${g.items[index][0]}」？`)){g.items.splice(Number(index),1);persist();renderGroups();toast('已从本机体验空间移除')}}});
document.addEventListener('change',e=>{if(e.target.dataset.groupStyle){styles[e.target.dataset.groupStyle]=e.target.value;persist();renderGroups()}});document.addEventListener('keydown',e=>{if(e.key==='Escape')$('.dock')?.classList.remove('open');if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();($('#search-input')||$('#filter'))?.focus()}});setInterval(()=>tick(),1000);matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>apply());

// Theme definitions keep home compositions and shared workspace tokens together.
const THEMES={
 base:{name:'基础风格',en:'ESSENTIAL',desc:'留白之间，轻松开始。',mode:'light',color:'#48614c',font:'sans',mini:'一 隅'},
 paper:{name:'报纸风',en:'THE DAILY',desc:'把你的收藏，编成今日头条。',mode:'light',color:'#45433c',font:'serif',mini:'一隅日报'},
 music:{name:'音乐风',en:'SIDE A',desc:'让每一刻，都有自己的节奏。',mode:'dark',color:'#bd9055',font:'serif',mini:'◉'},
 cinema:{name:'电影风',en:'NOW SHOWING',desc:'今天这部电影，由你主演。',mode:'dark',color:'#ba794f',font:'serif',mini:'此刻'},
 cosmos:{name:'宇宙风',en:'ORBIT',desc:'在浩瀚里，找到自己的坐标。',mode:'dark',color:'#8b83d1',font:'sans',mini:'◌'},
 flip:{name:'翻页时钟',en:'SLOW HOURS',desc:'看时间翻过，也让心慢下来。',mode:'dark',color:'#8295ac',font:'sans',mini:'12 : 48'},
 rain:{name:'数字雨',en:'FALLING TIME',desc:'让流动的时间，落在眼前。',mode:'dark',color:'#73a396',font:'sans',mini:'0 1 9'}
};
const PALETTES=[['#48614c','苔绿'],['#45433c','石墨'],['#bd9055','香槟'],['#467ea5','湖蓝'],['#8b83d1','星紫'],['#ba794f','落日'],['#a95e76','玫瑰']];
let playing=false,mood='松弛',focusSeconds=25*60,focusEnd=0,focusRunning=false,lastRainSecond='',lastRainMinute='',homeTimerMode='date',themeMemory=stored?.themeMemory||{};
const rawPersist=persist;
persist=function(){rawPersist();try{const s=JSON.parse(localStorage.getItem('yiyu-prototype-v1'));if(s){s.themeMemory=themeMemory;localStorage.setItem('yiyu-prototype-v1',JSON.stringify(s))}}catch{}};
function apply(){const p=effective(),t=THEMES[p.theme]||THEMES.base;const dark=p.mode==='dark'||p.mode==='system'&&matchMedia('(prefers-color-scheme: dark)').matches;document.body.dataset.theme=p.theme;document.body.dataset.dark=dark;document.body.dataset.view=view;document.documentElement.style.setProperty('--accent',p.color||t.color);document.documentElement.style.setProperty('--width',p.width==='wide'?'100%':'1120px');document.documentElement.style.setProperty('--font',p.font==='serif'?"Georgia, 'Songti SC', 'SimSun', serif":"Inter, 'Segoe UI', 'Microsoft YaHei', sans-serif");document.documentElement.style.setProperty('--display-font',t.font==='serif'?"Georgia, 'Songti SC', 'SimSun', serif":"'Segoe UI', 'Microsoft YaHei', sans-serif")}
function render(){apply();$('.account').textContent=signed?'体验中':'登录';view==='home'?home():workspace();dock()}
const timeText=()=>new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',hour12:false});
const dateText=()=>new Date().toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'long'});
function landscape(cls=''){return `<svg class="landscape ${cls}" viewBox="0 0 1200 700" role="img" aria-label="原创几何风景：山谷、落日与通向远方的道路" preserveAspectRatio="xMidYMid slice"><defs><linearGradient id="sky${cls}" x2="0" y2="1"><stop stop-color="#153842"/><stop offset="1" stop-color="#b9b6a0"/></linearGradient><linearGradient id="hill${cls}" x2="0" y2="1"><stop stop-color="#56706a"/><stop offset="1" stop-color="#142e35"/></linearGradient></defs><path fill="url(#sky${cls})" d="M0 0h1200v700H0z"/><circle cx="800" cy="250" r="110" fill="#ead7af"/><path fill="#9caa97" d="M0 470L210 270 370 430 530 310 780 450 980 270 1200 440V700H0z"/><path fill="url(#hill${cls})" d="M0 430Q180 360 440 550T1200 400V700H0z"/><path fill="#23483f" d="M0 540Q240 470 470 630L680 700H0z"/><path fill="#bdb89a" d="M635 700Q590 575 760 512Q840 480 790 460Q880 480 794 529Q683 586 777 700Z"/><path d="M86 602v-114m-23 59 23-44 25 44m-41-22 16-35 17 35M1091 565V435m-29 70 29-51 28 51m-46-27 18-37 19 37" stroke="#183831" stroke-width="10" fill="none"/></svg>`}
function standardAI(){return `<div class="ai-links"><span class="ai-label">和 AI 聊聊</span><a href="https://www.doubao.com" target="_blank" rel="noopener noreferrer"><span class="ai-icon">◕</span>豆包</a><a href="https://www.qianwen.com" target="_blank" rel="noopener noreferrer"><span class="ai-icon">✳</span>千问</a><a href="https://www.kimi.com" target="_blank" rel="noopener noreferrer"><span class="ai-icon">K</span>Kimi</a><a href="https://chat.deepseek.com" target="_blank" rel="noopener noreferrer"><span class="ai-icon">≈</span>DeepSeek</a></div>`}
function flipMarkup(){return `<div class="flip-face" aria-label="当前时间">${[0,1,2,3].map((_,i)=>`${i===2?'<span class="flip-colon">:</span>':''}<span class="digit" data-digit="${i}"><span class="digit-value">0</span><i class="digit-flap" aria-hidden="true">0</i><i class="digit-flap-bottom" aria-hidden="true">0</i></span>`).join('')}</div>`}
function home(){const p=effective(),theme=THEMES[p.theme]?p.theme:'base';let composition='';
 if(theme==='base')composition=`<div class="base-composition"><div class="eyebrow" data-live-date>${dateText()}</div><h1>你的互联网，自成一隅。</h1><p class="intro">收下喜欢的，随时再相逢。</p>${searchMarkup()}${standardAI()}</div>`;
 if(theme==='music')composition=musicComposition();
 if(theme==='cinema')composition=`<div class="cinema-composition"><div class="film-poster">${landscape('cinema')}<div class="poster-top"><span>YIYU ORIGINAL PICTURE</span><span>一部关于今天的电影</span></div><div class="poster-title"><span class="eyebrow">NOW SHOWING / 正在热映</span><h1>此刻，<br>即是好时光。</h1><p>每一个平凡的日子，都值得成为主角。</p></div><div class="poster-bottom"><span>DIRECTED BY YOU<br><small>由你执导 · 不设剧本</small></span><div>今日上映 <b data-live-time>${timeText()}</b></div><span class="film-rating">ALL AGES<br>无限可能</span></div></div><div class="film-ticket"><span>ADMIT ONE · 今日入场券</span><span data-live-date>${dateText()}</span><button data-v2="enter">进入你的故事 ↗</button></div></div>`;
 if(theme==='paper'){const featured=allItems().slice(0,3);composition=`<div class="newspaper"><div class="paper-meta"><span data-live-date>${dateText()}</span><span>私人珍藏 · 每日一刊</span><span>此刻 <b data-live-time>${timeText()}</b></span></div><div class="masthead"><h1>一隅日报</h1><span>THE YIYU DAILY · 你的世界，自成一版</span></div><div class="paper-columns"><article class="paper-lead"><div class="paper-kicker">今日封面 / EDITOR'S NOTE</div><h2>好奇心不打烊。<br>好东西，慢慢收藏。</h2>${landscape('paper')}<p>把散落在互联网的灵感，整理成属于自己的风景。</p></article><section class="paper-saved"><div class="paper-kicker">你的收藏 / COLLECTION</div>${featured.map((x,i)=>`<a href="${esc(x.item[1])}" target="_blank" rel="noopener noreferrer"><small>0${i+1} / ${esc(x.path.split(' / ')[0])}</small><h3>${esc(x.item[0])} ↗</h3><p>${esc(x.item[2])}</p></a>`).join('')}</section><aside class="paper-index"><div class="paper-kicker">版面索引</div>${data.map((s,i)=>`<button data-space="${s.id}"><small>SECTION 0${i+1}</small><b>${esc(s.name)}</b><span>${s.scenes.reduce((n,c)=>n+c.groups.reduce((a,g)=>a+g.items.length,0),0)} 条收藏 ↗</span></button>`).join('')}<div class="paper-quote">“让值得留下的，<br>都有一个归处。”</div></aside></div><div class="paper-bottom">独立编辑 · 长期珍藏 <span>YIYU / EST. 2026</span></div></div>`}
 if(theme==='cosmos')composition=cosmosComposition();
 if(theme==='flip')composition=`<div class="flip-composition"><div class="eyebrow">MAKE ROOM FOR THE PRESENT</div><div class="clock-switch"><button data-v2="date-mode" class="${homeTimerMode==='date'?'selected':''}">当前时间</button><button data-v2="focus-mode" class="${homeTimerMode==='focus'?'selected':''}">专注模式</button></div>${flipMarkup()}<div class="flip-caption" data-live-date>${dateText()}</div><div class="focus-controls" ${homeTimerMode==='focus'?'':'hidden'}><button class="primary" data-v2="focus-toggle">${focusRunning?'暂停专注':'开始专注'}</button><button data-v2="focus-reset">重置 25 分钟</button><span>一次，只做一件事。</span></div></div>`;
 if(theme==='rain')composition=`<div class="rain-composition"><div class="rain-heading"><span class="eyebrow">EVERY SECOND FINDS ITS PLACE</span><p>每一秒，都算数。</p></div><div class="rain-field" id="rain-field" aria-hidden="true"></div><div class="rain-landed"><div class="rain-hour" data-rain-hour>${timeText().split(':')[0]}</div><div class="rain-date"><span data-live-date>${dateText()}</span><small>时间在流动，你在此刻。</small></div><div class="rain-minute" data-rain-minute>${timeText().split(':')[1]}</div></div></div>`;
 $('#main').innerHTML=`<section class="home home-${theme}">${composition}${theme!=='base'?`<div class="utility-search"><button data-v2="quick-search" aria-label="打开搜索">⌕ <span>搜索网页或收藏</span><kbd>/</kbd></button></div>`:''}<button class="scroll-invitation" data-v2="enter">向下滚动，进入我的空间 <span>↓</span></button></section>`;
 if($('#search-form')){$('#search-form').onsubmit=submitSearch;$('#search-input').oninput=()=>{if(searchType==='saved')savedSearch()}}lastRainSecond='';lastRainMinute='';tick();if(theme==='cosmos')startOrbits();
}
function renderSettings(){const p=scope==='scene'?{...prefs,...overrides[sceneId]}:prefs;$('#settings h2').textContent='主题风格';$('#settings-body').innerHTML=`<p class="settings-intro">选一种风格，开启你的日常。</p>${view==='space'?`<div class="segmented"><button data-scope="global" class="${scope==='global'?'selected':''}">全局主题</button><button data-scope="scene" class="${scope==='scene'?'selected':''}">当前场景</button></div>`:''}<p class="scope-note">${scope==='scene'?`仅设置「${esc(scene().name)}」，其他场景不受影响。`:'应用到首页与空间；已自定义的场景保留自己的设置。'}</p><div class="themes theme-gallery">${Object.entries(THEMES).map(([id,t])=>`<button class="theme-tile ${p.theme===id?'selected':''}" data-v2-theme="${id}" aria-pressed="${p.theme===id}"><div class="theme-preview mini-${id}"><span>${t.mini}</span>${id==='music'?'<i class="mini-record"></i>':''}</div><div class="theme-tile-label"><b>${t.name}</b><span>${p.theme===id?'✓':t.en}</span></div><small>${t.desc}</small></button>`).join('')}</div><section class="setting-section"><h3>明暗模式${inheritLabel('mode')}</h3>${choices('mode',[['light','浅色'],['dark','深色'],['system','跟随系统']],p)}</section><section class="setting-section"><h3>主色${inheritLabel('color')}</h3><div class="swatches">${PALETTES.map(([v,n])=>`<button class="swatch ${p.color===v?'selected':''}" style="--swatch:${v}" data-pref="color" data-value="${v}" title="${n}" aria-label="${n}"></button>`).join('')}</div></section><details class="more-settings"><summary>字体与页面宽度</summary><section class="setting-section"><h3>字体${inheritLabel('font')}</h3>${choices('font',[['sans','清晰现代'],['serif','人文书写']],p)}</section><section class="setting-section"><h3>空间页宽度${inheritLabel('width')}</h3>${choices('width',[['safe','舒适留白'],['wide','横向铺开']],p)}</section></details>${scope==='scene'?'<button class="reset" data-action="reset-scene">全部恢复跟随全局</button>':''}<p class="setting-footer">即时预览 · 自动保存在本机</p>`}
function dock(){const theme=effective().theme;const objects={paper:'<span class="dock-object paper-object">日 報</span>',music:'<span class="dock-object record-object">◉</span>',cinema:'<span class="dock-object cinema-object">▰</span>',cosmos:'<span class="dock-object cosmos-object">◎</span>',flip:'<span class="dock-object">◷</span>',rain:'<span class="dock-object rain-object">01</span>'};$('#dock').innerHTML=`<div class="dock"><div class="dock-options">${data.map(s=>`<button class="space-option" data-space="${s.id}"><span>${s.icon}</span><small>${esc(s.name)}</small></button>`).join('')}</div><button class="dock-trigger" data-action="dock" aria-label="展开空间入口" aria-expanded="false">${objects[theme]||'<div class="train" aria-hidden="true"><span class="carriage"></span><span class="carriage"></span><span class="carriage engine"></span></div><div class="train-track"></div>'}<span class="dock-label">${view==='home'?'我的空间':'切换空间'}</span></button></div>${view==='space'?'<button class="return-cover" data-v2="return">↑ 返回封面</button>':''}`}
function changeTheme(id){const target=scope==='scene'?(overrides[sceneId]??={}):prefs,current={...prefs,...(scope==='scene'?target:{})},key=scope==='scene'?sceneId:'global';themeMemory[key]??={};themeMemory[key][current.theme]={mode:current.mode,color:current.color,font:current.font};const t=THEMES[id];Object.assign(target,{theme:id,layout:'search',color:t.color,font:t.font},themeMemory[key][id]||{},{mode:current.mode},prefs.explicitFont?{font:prefs.font}:{});persist();render();renderSettings()}
function tick(){const now=new Date(),text=timeText();document.querySelectorAll('[data-live-time]').forEach(el=>el.textContent=text);document.querySelectorAll('[data-live-date]').forEach(el=>el.textContent=dateText());if(focusRunning){focusSeconds=Math.max(0,Math.ceil((focusEnd-Date.now())/1000));if(!focusSeconds){focusRunning=false;toast('这一段专注完成了，休息一下吧。');const b=$('[data-v2="focus-toggle"]');if(b)b.textContent='开始专注'}}const digits=homeTimerMode==='focus'?`${String(Math.floor(focusSeconds/60)).padStart(2,'0')}${String(focusSeconds%60).padStart(2,'0')}`:text.replace(':','');document.querySelectorAll('[data-digit]').forEach((el,i)=>{const v=digits[i];if(el.dataset.value!==v){const old=el.dataset.value||v;el.dataset.value=v;el.querySelector('.digit-value').textContent=v;const flap=el.querySelector('.digit-flap');flap.textContent=old;let lower=el.querySelector('.flip-old-bottom');if(!lower){lower=document.createElement('i');lower.className='flip-old-bottom';lower.setAttribute('aria-hidden','true');el.append(lower)}lower.textContent=old;el.querySelector('.digit-flap-bottom').textContent=v;el.classList.remove('flipping');void el.offsetWidth;el.classList.add('flipping')}});const field=$('#rain-field');if(field&&!document.hidden){const minute=text,second=String(now.getSeconds()).padStart(2,'0');if(lastRainMinute!==minute){field.replaceChildren();lastRainMinute=minute;const h=$('[data-rain-hour]'),m=$('[data-rain-minute]');updateRainPart(h,text.split(':')[0],'hour');updateRainPart(m,text.split(':')[1],'minute')}if(lastRainSecond!==second){lastRainSecond=second;const n=document.createElement('span');n.className='rain-drop';n.textContent=second;n.style.setProperty('--x',(8+((now.getSeconds()*37)%85))+'%');n.style.setProperty('--drift',((now.getSeconds()%5)-2)*11+'px');n.style.setProperty('--angle',((now.getSeconds()%7)-3)*7+'deg');field.append(n)}}}
let transitionUntil=0,upArmedAt=0,gestureTotal=0,lastWheelAt=0,touchStart=null,wheelBurstHandled=false;
function changeView(next){if(view===next||Date.now()<transitionUntil)return;const previous=view;view=next;transitionUntil=Date.now()+850;upArmedAt=0;gestureTotal=0;render();window.scrollTo({top:0,behavior:'instant'});if(!matchMedia('(prefers-reduced-motion: reduce)').matches)$('#main').animate([{opacity:0,transform:`translateY(${previous==='home'?'75px':'-75px'})`},{opacity:1,transform:'translateY(0)'}],{duration:550,easing:'cubic-bezier(.2,.7,.2,1)'})}
function navigationGesture(delta){if(Date.now()<transitionUntil)return;const doc=document.documentElement;if(view==='home'&&delta>0&&window.scrollY+innerHeight>=doc.scrollHeight-8){changeView('space');return}if(view==='space'&&delta<0&&window.scrollY<=2){if(upArmedAt&&Date.now()-upArmedAt>350&&Date.now()-upArmedAt<2600)changeView('home');else{upArmedAt=Date.now();toast('再向上滑一次，回到封面')}}}
window.addEventListener('wheel',e=>{if(document.querySelector('dialog[open]')||e.ctrlKey||Math.abs(e.deltaX)>Math.abs(e.deltaY)||e.target.closest('input,select,textarea,.results,.dock-options,.sidebar,.group-tabs'))return;const now=Date.now(),gap=now-lastWheelAt;lastWheelAt=now;if(gap>160){gestureTotal=0;wheelBurstHandled=false}gestureTotal+=e.deltaY*(e.deltaMode===1?16:1);const boundary=view==='home'?window.scrollY+innerHeight>=document.documentElement.scrollHeight-8:window.scrollY<=2;if(boundary&&((view==='home'&&e.deltaY>0)||(view==='space'&&e.deltaY<0))){e.preventDefault();if(Math.abs(gestureTotal)>65&&!wheelBurstHandled){navigationGesture(gestureTotal);wheelBurstHandled=true;gestureTotal=0}}},{passive:false});
window.addEventListener('touchstart',e=>{if(e.touches.length===1&&!document.querySelector('dialog[open]')&&!e.target.closest('input,select,button,a,.results,.sidebar,.group-tabs'))touchStart={y:e.touches[0].clientY,top:scrollY};else touchStart=null},{passive:true});
window.addEventListener('touchend',e=>{if(!touchStart||!e.changedTouches.length)return;const d=touchStart.y-e.changedTouches[0].clientY;if(Math.abs(d)>65&&(view==='home'||touchStart.top<=2))navigationGesture(d);touchStart=null},{passive:true});
function quickSearch(){let dialog=$('#quick-search');if(!dialog){dialog=document.createElement('dialog');dialog.id='quick-search';dialog.addEventListener('close',()=>{if(!dialog.open)dialog.replaceChildren()});document.body.append(dialog)}dialog.innerHTML=`<div class="dialog-heading"><h2>开始探索</h2><button class="icon-button" data-action="close" aria-label="关闭搜索">×</button></div>${searchMarkup()}${standardAI()}`;if(!dialog.open)dialog.showModal();$('#search-form').onsubmit=submitSearch;$('#search-input').oninput=()=>{if(searchType==='saved')savedSearch()};$('#search-input').focus()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.v2Theme){changeTheme(b.dataset.v2Theme);return}const action=b.dataset.v2;if(action==='enter')changeView('space');if(action==='return')changeView('home');if(action==='quick-search')quickSearch();if(action==='play'){playing=!playing;home()}if(action==='mood-prev'||action==='mood-next'){const moods=['松弛','专注','轻快','放空'];mood=moods[(moods.indexOf(mood)+(action==='mood-next'?1:3))%moods.length];home()}if(action==='date-mode'||action==='focus-mode'){homeTimerMode=action==='date-mode'?'date':'focus';home()}if(action==='focus-toggle'){if(focusRunning){focusSeconds=Math.max(0,Math.ceil((focusEnd-Date.now())/1000));focusRunning=false}else{if(!focusSeconds)focusSeconds=1500;focusEnd=Date.now()+focusSeconds*1000;focusRunning=true}home()}if(action==='focus-reset'){focusRunning=false;focusSeconds=1500;home()}},false);
document.addEventListener('keydown',e=>{if(e.key==='/'&&view==='home'&&!$('#search-input')&&!document.querySelector('dialog[open]')&&!e.target.closest('input,textarea,select')){e.preventDefault();quickSearch()}if(e.key==='PageDown'&&!document.querySelector('dialog[open]')&&view==='home'){e.preventDefault();changeView('space')}if(e.key==='PageUp'&&!document.querySelector('dialog[open]')&&view==='space'&&scrollY<=2){e.preventDefault();navigationGesture(-100)}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)tick()});
