// Procedural, original ambient pieces: no remote audio, no autoplay.
const TRACKS=[
 {name:'晨雾',mood:'松弛',beat:0.68,chords:[[48,55,60,64],[45,52,57,60],[53,60,65,69],[43,50,55,59]],melody:[72,null,76,79,null,76,74,null,72,67,null,69,72,null,71,null]},
 {name:'微光',mood:'专注',beat:0.56,chords:[[50,57,62,65],[46,53,58,62],[53,60,65,69],[48,55,60,64]],melody:[74,77,null,81,77,null,74,null,72,69,null,72,77,null,76,null]},
 {name:'晚风',mood:'放空',beat:0.84,chords:[[48,55,59,64],[53,60,64,69],[45,52,57,60],[43,50,59,62]],melody:[79,null,null,76,74,null,72,null,71,null,74,null,72,null,null,null]}
];
let trackIndex=0,audioCtx=null,audioMaster=null,audioVoiceBus=null,audioLoop=null,audioStep=0,nextNoteAt=0,muted=false,audioBusy=false;
function initAudio(){if(audioCtx)return;const Context=window.AudioContext||window.webkitAudioContext;if(!Context)throw new Error('audio unavailable');audioCtx=new Context();audioMaster=audioCtx.createGain();audioMaster.gain.value=muted?0:0.45;const compressor=audioCtx.createDynamicsCompressor();compressor.threshold.value=-18;compressor.ratio.value=4;audioMaster.connect(compressor);compressor.connect(audioCtx.destination)}
function makeVoiceBus(){const bus=audioCtx.createGain();bus.gain.value=1;bus.connect(audioMaster);const convolver=audioCtx.createConvolver(),wet=audioCtx.createGain();const length=Math.floor(audioCtx.sampleRate*2.8),buffer=audioCtx.createBuffer(2,length,audioCtx.sampleRate);for(let channel=0;channel<2;channel++){const samples=buffer.getChannelData(channel);for(let i=0;i<length;i++)samples[i]=(Math.random()*2-1)*Math.pow(1-i/length,3.5)}convolver.buffer=buffer;wet.gain.value=.18;bus.connect(convolver);convolver.connect(wet);wet.connect(audioMaster);audioVoiceBus={bus,convolver,wet};}
function releaseBus(){if(!audioVoiceBus)return;const old=audioVoiceBus;audioVoiceBus=null;old.bus.gain.cancelScheduledValues(audioCtx.currentTime);old.bus.gain.setTargetAtTime(0,audioCtx.currentTime,.025);setTimeout(()=>{old.bus.disconnect();old.convolver.disconnect();old.wet.disconnect()},180)}
function note(midi,at,duration,volume,pad=false){const oscillator=audioCtx.createOscillator(),gain=audioCtx.createGain();oscillator.type='sine';oscillator.frequency.value=440*Math.pow(2,(midi-69)/12);gain.gain.setValueAtTime(0,at);gain.gain.linearRampToValueAtTime(volume,at+(pad?.45:.016));gain.gain.exponentialRampToValueAtTime(.0001,at+duration);oscillator.connect(gain);gain.connect(audioVoiceBus.bus);oscillator.start(at);oscillator.stop(at+duration+.03);oscillator.onended=()=>{oscillator.disconnect();gain.disconnect()};if(!pad){const harmonic=audioCtx.createOscillator(),overtone=audioCtx.createGain();harmonic.frequency.value=oscillator.frequency.value*2;harmonic.type='sine';overtone.gain.setValueAtTime(volume*.14,at);overtone.gain.exponentialRampToValueAtTime(.0001,at+duration*.48);harmonic.connect(overtone);overtone.connect(audioVoiceBus.bus);harmonic.start(at);harmonic.stop(at+duration*.5);harmonic.onended=()=>{harmonic.disconnect();overtone.disconnect()}}}
function scheduleMusic(){if(!playing||!audioVoiceBus||audioCtx.state!=='running')return;const t=TRACKS[trackIndex];if(nextNoteAt<audioCtx.currentTime-.1)nextNoteAt=audioCtx.currentTime+.04;while(nextNoteAt<audioCtx.currentTime+.35){const chord=t.chords[Math.floor(audioStep/16)%4],melody=t.melody[audioStep%16];if(audioStep%16===0)chord.forEach(n=>note(n,nextNoteAt,t.beat*14,.045,true));if(audioStep%4===0)note(chord[(audioStep/4)%4]+12,nextNoteAt,t.beat*3,.095);if(melody!==null)note(melody,nextNoteAt,t.beat*3.5,.105);audioStep++;nextNoteAt+=t.beat}}
async function toggleMusic(){if(audioBusy)return;audioBusy=true;try{initAudio();if(playing){playing=false;clearInterval(audioLoop);audioLoop=null;await audioCtx.suspend()}else{await audioCtx.resume();if(!audioVoiceBus)makeVoiceBus();playing=true;nextNoteAt=audioCtx.currentTime+.05;scheduleMusic();audioLoop=setInterval(scheduleMusic,120)}syncMusicUI()}catch{playing=false;toast('当前浏览器无法播放，请再试一次');syncMusicUI()}finally{audioBusy=false}}
function chooseTrack(index){trackIndex=index;audioStep=0;if(audioCtx){releaseBus();makeVoiceBus();nextNoteAt=audioCtx.currentTime+.07;scheduleMusic()}syncMusicUI()}
function toggleMute(){muted=!muted;if(audioMaster)audioMaster.gain.setTargetAtTime(muted?0:.45,audioCtx.currentTime,.04);syncMusicUI()}
function syncMusicUI(){const play=$('[data-v3="audio-play"]');if(!play)return;play.textContent=playing?'Ⅱ':'▶';play.setAttribute('aria-label',playing?'暂停音乐':'播放音乐');play.setAttribute('aria-pressed',String(playing));$('.vinyl')?.classList.toggle('spinning',playing);$('.tonearm')?.classList.toggle('engaged',playing);$('.equalizer')?.classList.toggle('moving',playing&&!muted);const mute=$('[data-v3="audio-mute"]');mute.innerHTML=muted?'静音 <span>×</span>':'声音 <span>♪</span>';mute.setAttribute('aria-label',muted?'取消静音':'静音');mute.setAttribute('aria-pressed',String(muted));$('#track-select').value=String(trackIndex);$('.player-caption').textContent=`${TRACKS[trackIndex].mood} · ${playing?(muted?'静音中':'正在播放'):'点击播放'} · 原创轻音乐`;}
function musicComposition(){return `<div class="music-composition"><div class="record-sleeve"><div class="vinyl ${playing?'spinning':''}"><div class="vinyl-label"><span>SIDE A</span><b>此刻</b><small>THE SOUND OF TODAY</small><i class="spindle"></i></div></div><div class="tonearm ${playing?'engaged':''}" aria-hidden="true"><span class="arm-pivot"></span><span class="arm-shaft"></span><span class="arm-head"></span></div><span class="record-calibration" aria-hidden="true">33⅓ &nbsp; • &nbsp; STEREO</span></div><div class="music-info"><div class="eyebrow">THE SOUND OF YOUR DAY</div><h1>把此刻，<br>调到喜欢的频率。</h1><div class="music-time" data-live-time>${timeText()}</div><div class="music-date" data-live-date>${dateText()}</div><div class="play-progress"><span id="music-progress"></span></div><div class="player-controls"><button class="play-toggle" data-v3="audio-play" aria-label="${playing?'暂停音乐':'播放音乐'}">${playing?'Ⅱ':'▶'}</button><select id="track-select" aria-label="选择轻音乐">${TRACKS.map((t,i)=>`<option value="${i}" ${i===trackIndex?'selected':''}>${t.name} · ${t.mood}</option>`).join('')}</select><button class="mute-control" data-v3="audio-mute" aria-label="${muted?'取消静音':'静音'}">${muted?'静音 ×':'声音 ♪'}</button><span class="equalizer ${playing&&!muted?'moving':''}" aria-hidden="true"><i></i><i></i><i></i><i></i></span></div><span class="player-caption">${TRACKS[trackIndex].mood} · ${playing?(muted?'静音中':'正在播放'):'点击播放'} · 原创轻音乐</span></div></div>`}

const PLANETS=[{id:'violet',name:'紫星',color:'#aaa0c9',shadow:'#22263e',size:40},{id:'ocean',name:'海蓝星',color:'#83adb6',shadow:'#193b4c',size:44},{id:'sand',name:'沙金星',color:'#b8a387',shadow:'#554537',size:37},{id:'moss',name:'青岚星',color:'#8fa993',shadow:'#2c443e',size:31},{id:'rose',name:'赤砂星',color:'#b6867c',shadow:'#4d2e38',size:35},{id:'moon',name:'月白星',color:'#bfc5c4',shadow:'#434b56',size:26}];
let centerPlanet='violet',orbitFrameId=0,orbitPositions={},orbitRefresh=null;
function cosmosComposition(){return `<div class="cosmos-composition"><div class="orbit-system" role="group" aria-label="环绕星球，点击可切换中心"><div class="orbit o1"></div><div class="orbit o2"></div>${PLANETS.map(p=>`<button class="orbit-body" data-planet="${p.id}" style="--planet-light:${p.color};--planet-shadow:${p.shadow}" aria-label="${p.name}${p.id===centerPlanet?'，当前中心':'，设为中心'}" aria-pressed="${p.id===centerPlanet}"><span class="planet-surface"></span><span class="planet-name">${p.name}</span></button>`).join('')}<span class="orbit-hint">点击星球，切换中心</span></div><div class="cosmos-copy"><span class="eyebrow">PERSONAL OBSERVATORY / 个人观测站</span><h1>漫游宇宙，<br>也回到自己。</h1><div class="cosmos-time" data-live-time>${timeText()}</div><span class="cosmos-date" data-live-date>${dateText()}</span></div><span class="coordinates">LOCAL TIME<br>EARTH · SOLAR SYSTEM<br>宇宙很大，这里属于你。</span></div>`}
function startOrbits(){cancelAnimationFrame(orbitFrameId);const container=$('.orbit-system');if(!container)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let last=performance.now();function frame(now){if(!container.isConnected)return;const blend=reduced?1:1-Math.exp(-Math.min(60,now-last)/145);last=now;const others=PLANETS.filter(p=>p.id!==centerPlanet);PLANETS.forEach(p=>{const el=container.querySelector(`[data-planet=${p.id}]`),central=p.id===centerPlanet,index=others.indexOf(p),angle=(reduced?0:now/1000)*(0.07+index*.011)+index*1.23,rx=190+index*13,ry=95+index*10,rotation=-.42;const xx=Math.cos(angle)*rx,yy=Math.sin(angle)*ry;const target={x:central?307.5:307.5+xx*Math.cos(rotation)-yy*Math.sin(rotation),y:central?242.5:242.5+xx*Math.sin(rotation)+yy*Math.cos(rotation),size:central?275:p.size};const pos=orbitPositions[p.id]??={...target};for(const k of ['x','y','size'])pos[k]+=(target[k]-pos[k])*blend;el.style.width=pos.size+'px';el.style.height=pos.size+'px';el.style.transform=`translate(${pos.x-pos.size/2}px,${pos.y-pos.size/2}px)`;el.style.zIndex=central?'4':(Math.sin(angle)>.15?'6':'2');el.classList.toggle('is-center',central);el.setAttribute('aria-pressed',String(central));el.setAttribute('aria-label',`${p.name}${central?'，当前中心':'，设为中心'}`)});if(!reduced)orbitFrameId=requestAnimationFrame(frame)}orbitRefresh=()=>frame(performance.now());orbitRefresh()}

let rainPrevious={hour:null,minute:null};
function updateRainPart(el,value,key){if(!el)return;const previous=rainPrevious[key],changed=previous!==value;rainPrevious[key]=value;if(!changed){if(!el.querySelector('.rain-value'))el.innerHTML=`<span class="rain-value">${value}</span>`;return}el.innerHTML=`<span class="rain-value">${value}</span>`;el.setAttribute('aria-label',`${key==='hour'?'小时':'分钟'} ${value}`);if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const incoming=el.querySelector('.rain-value');incoming.animate([{transform:'translateY(-420px)',opacity:0},{transform:'translateY(-60px)',opacity:1,offset:.62},{transform:'translateY(7px)',opacity:1,offset:.84},{transform:'translateY(0)',opacity:1}],{duration:1000,easing:'cubic-bezier(.38,.02,.68,1)'});if(previous!==null){const old=document.createElement('span');old.className='rain-old';old.textContent=previous;old.setAttribute('aria-hidden','true');el.append(old);const animation=old.animate([{transform:'translateY(0) scale(1)',opacity:1},{transform:'translateY(0) scale(1)',opacity:1,offset:.68},{transform:'translateY(55px) scale(.7,.2)',opacity:0}],{duration:1000,easing:'ease-in',fill:'forwards'});animation.onfinish=()=>old.remove()}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.v3==='audio-play')toggleMusic();if(b.dataset.v3==='audio-mute')toggleMute();if(b.dataset.planet&&centerPlanet!==b.dataset.planet){centerPlanet=b.dataset.planet;if(matchMedia('(prefers-reduced-motion: reduce)').matches)orbitRefresh?.()}});
document.addEventListener('change',e=>{if(e.target.id==='track-select')chooseTrack(Number(e.target.value))});
window.addEventListener('pagehide',()=>{clearInterval(audioLoop);audioCtx?.close();cancelAnimationFrame(orbitFrameId)});
